    jsonb_build_object('type', $$p$$, 'text', $$ລາວຖືວ່ານີ້ຄືຄວາມສ່ຽງທາງເຕັກນິກທີ່ແທ້ຈິງ ບໍ່ໄດ້ປັດປ່ອຍມັນຖິ້ມ ແລະ ຊີ້ໄປທີ່ຄວາມສາມາດຂອງເຄືອຂ່າຍ ໃນການຮັບເອົາການປ່ຽນແປງດ້ວຍການເຫັນດີເຫັນຮ່ວມ. ຜູ້ອ່ານຄວນສັງເກດວ່າ ນີ້ເປັນດາບສອງຄົມ: ເຄືອຂ່າຍທີ່ປັບຕົວໄດ້ ກໍ່ຄືເຄືອຂ່າຍທີ່ກົດເກນຂອງມັນ ບໍ່ໄດ້ "ປ່ຽນແປງບໍ່ໄດ້" ຫຼາຍປານທີ່ຂໍ້ໂຕ້ແຍ້ງອັນແຮງກ້າທີ່ສຸດຮຽກຮ້ອງ.$$)
  )),
    jsonb_build_object('heading', $$ຄວນອ່ານປຶ້ມນີ້ແນວໃດ$$, 'blocks', jsonb_build_array(
    jsonb_build_object('type', $$p$$, 'text', $$The Bitcoin Standard ຄືຂໍ້ໂຕ້ແຍ້ງ ຂຽນໂດຍຜູ້ສະໜັບສະໜູນ ໃນຮູບແບບທີ່ອ່ານຄືປະຫວັດສາດ. ນັ້ນບໍ່ແມ່ນເຫດຜົນທີ່ຈະຂ້າມມັນ — ມັນເປັນໜຶ່ງໃນການອະທິບາຍຈຸດຢືນທີ່ຊັດເຈນ ແລະ ສອດຄ່ອງທີ່ສຸດອັນໜຶ່ງ ແລະ ມັນຈະເຮັດໃຫ້ຄວາມຄິດຂອງທ່ານຄົມຂຶ້ນ ບໍ່ວ່າທ່ານຈະເຫັນດີໃນທີ່ສຸດຫຼືບໍ່. ແຕ່ໃຫ້ອ່ານມັນໂດຍຈື່ຈຸດຕໍ່ໄປນີ້ໄວ້ໃນໃຈ.$$),
    jsonb_build_object('type', $$list$$, 'items', jsonb_build_array(
    jsonb_build_object('label', $$ປະຫວັດສາດເສດຖະກິດຖືກເລືອກມາສະເພາະສ່ວນ.$$, 'body', $$ຍຸກມາດຕະຖານຄຳຄລາສສິກ ຖືກນຳສະເໜີວ່າເປັນຄວາມສຳເລັດທີ່ບໍ່ມີຂໍ້ຂ້ອງໃຈ. ນັກປະຫວັດສາດເສດຖະກິດຊີ້ໄປທີ່ວິກິດທະນາຄານທີ່ເກີດຊ້ຳໆໃນຍຸກນັ້ນ, ຄວາມກົດດັນຈາກເງິນຝືດຕໍ່ຜູ້ເປັນໜີ້ ແລະ ຊາວກະສິກອນ ແລະ ມຸມມອງທີ່ຖືກຍອມຮັບຢ່າງກວ້າງຂວາງວ່າ ການຍຶດຕິດກັບຄຳ ເຮັດໃຫ້ພາວະຖົດຖອຍໃຫຍ່ (Great Depression) ເລິກ ແລະ ຍາວຂຶ້ນ. Ammous ກ່າວເຖິງສິ່ງເຫຼົ່ານີ້ ແຕ່ບໍ່ໄດ້ເນັ້ນຢູ່ນຳມັນ.$$),
    jsonb_build_object('label', $$ຄຳຖາມເລື່ອງເງິນຝືດຍັງເປັນປະເດັນຖົກຖຽງແທ້ໆ.$$, 'body', $$ລາວໂຕ້ແຍ້ງວ່າ ລາຄາທີ່ຄ່ອຍໆລົດລົງ ຄືຜົນລັບທຳມະຊາດ ແລະ ເປັນປະໂຫຍດ ຈາກການເຕີບໂຕຂອງຜະລິດຕະພາບ. ຄວາມກັງວົນຂອງກະແສຫຼັກ ບໍ່ແມ່ນລາຄາທີ່ຫຼຸດເອງ ແຕ່ແມ່ນໜີ້ສິນ: ເມື່ອໜີ້ສິນເປັນຕົວເລກຄົງທີ່ ແລະ ລາຄາຫຼຸດລົງ ພາລະໜີ້ສິນຕົວຈິງຈະເພີ່ມຂຶ້ນ ແລະ ວົງຈອນທີ່ເກີດຈາກສິ່ງນີ້ ຄືກົນໄກທີ່ນັກເສດຖະສາດສ່ວນໃຫຍ່ໂທດວ່າເປັນສາເຫດຂອງປີທີ່ຮ້າຍແຮງທີ່ສຸດຂອງຊຸມປີ 1930. ຄວາມເຫັນຕ່າງນີ້ບໍ່ແມ່ນລາຍລະອຽດນ້ອຍໆ — ຫຼາຍຢ່າງຕິດຕາມມາຈາກມັນ.$$),
    jsonb_build_object('label', $$ໂມເດວ stock-to-flow ໃນຖານະການທຳນາຍລາຄາ ບໍ່ໄດ້ພິສູດຕົວມັນເອງ.$$, 'body', $$ອັດຕາສ່ວນນີ້ເປັນວິທີທີ່ສົມເຫດສົມຜົນ ໃນການນິຍາມຄວາມແຂງ. ແຕ່ໂມເດວທີ່ນິຍົມ ຊຶ່ງໃຊ້ມັນທຳນາຍລະດັບລາຄາສະເພາະ ໄດ້ບ່ຽງເບນອອກຈາກຄວາມເປັນຈິງຢ່າງແຮງ ໃນຫຼາຍປີຫຼັງຈາກປຶ້ມພິມ ແລະ ຄວນແຍກການໃຊ້ນິຍາມຂອງ Ammous ອອກຈາກເຄື່ອງມືນັ້ນທີ່ມາພາຍຫຼັງ.$$),
    jsonb_build_object('label', $$ປຶ້ມນີ້ຂຽນໃນປີ 2018.$$, 'body', $$ຂຽນກ່ອນການຮັບຮອງເອົາຂອງສະຖາບັນການເງິນ, ກ່ອນ spot ETF, ກ່ອນ El Salvador, ກ່ອນການລົ້ມຂອງຄົນກາງລວມສູນລາຍໃຫຍ່, ກ່ອນເງິນຕາດິຈິຕອນຂອງທະນາຄານກາງ (CBDC) ຈະກາຍເປັນນະໂຍບາຍຈິງ ແລະ ກ່ອນເຫດການເງິນເຟີ້ຊຸມປີ 2021-23 ຈະເປັນການທົດສອບໂດຍກົງຕໍ່ຫຼາຍຄຳກ່າວອ້າງຂອງມັນ. ຕອນນີ້ ຄຳທຳນາຍຂອງມັນສາມາດຖືກກວດສອບໄດ້ຈິງ ບໍ່ແມ່ນພຽງແຕ່ຖືກປະເມີນ.$$),
    jsonb_build_object('label', $$ການໃຊ້ງານຈິງແຕກຕ່າງຈາກທິດສະດີ.$$, 'body', $$ຜູ້ຖືສ່ວນໃຫຍ່ ປະຕິບັດຕໍ່ Bitcoin ຄືຊັບສິນເກັງກຳໄລ ທີ່ຄ້າຂາຍຕາມຄວາມກ້າສ່ຽງ ບໍ່ແມ່ນເປັນເຄື່ອງມືປ້ອງກັນຄວາມສ່ຽງທາງການເງິນ ແລະ ຄວາມສຳພັນຂອງມັນກັບຮຸ້ນໃນຊ່ວງຕະຫຼາດຕຶງຄຽດ ໄດ້ເຮັດໃຫ້ກອບແນວຄິດ "ບ່ອນເກັບມູນຄ່າລ້ວນໆ" ອັບອາຍຊ້ຳແລ້ວຊ້ຳອີກ. Ammous ຄົງຈະບອກວ່າໄລຍະເວລາຍັງສັ້ນເກີນໄປທີ່ຈະຕັດສິນ ຊຶ່ງເປັນຄຳຕອບທີ່ຍຸຕິທຳ ແຕ່ກໍ່ພິສູດຜິດບໍ່ໄດ້ເຊັ່ນກັນ.$$),
    jsonb_build_object('label', $$ບົດວັດທະນະທຳແມ່ນຄວາມຄິດເຫັນ.$$, 'body', $$ເນື້ອຫາກ່ຽວກັບສິລະປະ, ສະຖາປັດຕະຍະກຳ, ອາຫານ ແລະ ຄອບຄົວ ຖືກນຳສະເໜີດ້ວຍຄວາມໝັ້ນໃຈເທົ່າກັບເສດຖະສາດການເງິນ ແຕ່ອີງໃສ່ຫຼັກຖານທີ່ບາງກວ່າຫຼາຍ.$$)
  )),
    jsonb_build_object('type', $$p$$, 'text', $$ວິທີທີ່ເປັນປະໂຫຍດໃນການເບິ່ງທັງໝົດນີ້: ຈຸດແຂງທີ່ສຸດຂອງປຶ້ມ ຄືກອບແນວຄິດ — ຄວາມສາມາດຂາຍຕໍ່ໄດ້, ຄວາມແຂງ, stock-to-flow, time preference, ປະກົດການ Cantillon. ເຄື່ອງມືເຫຼົ່ານີ້ຊ່ວຍໃຫ້ຄວາມຄິດແຈ່ມແຈ້ງຂຶ້ນຢ່າງແທ້ຈິງ ແລະ ຢູ່ໄດ້ເອງ ບໍ່ຂຶ້ນກັບຂໍ້ສະຫຼຸບທີ່ Ammous ດຶງອອກມາຈາກມັນ. ສ່ວນທີ່ອ່ອນທີ່ສຸດ ຄືຄຳຕັດສິນທາງປະຫວັດສາດ ແລະ ວັດທະນະທຳແບບກວ້າງໆ. ທ່ານສາມາດເອົາເຄື່ອງມືເຫຼົ່ານັ້ນໄປໃຊ້ ແລ້ວຫາຄຳຕັດສິນຂອງທ່ານເອງ.$$),
    jsonb_build_object('type', $$p$$, 'text', $$ຖ້າທ່ານຢາກໄດ້ຍິນອີກຝ່າຍໜຶ່ງໂຕ້ແຍ້ງຢ່າງເປັນທຳ ບໍ່ແມ່ນຖືກເຮັດໃຫ້ເປັນຕົວຕະຫຼົກ ໃຫ້ຊອກຫາການວິຈານຈາກນັກຂຽນສາຍ post-Keynesian ແລະ ປະຫວັດສາດການເງິນ ແລະ ອ່ານຫຍັງກໍ່ຕາມທີ່ໜັກແໜ້ນກ່ຽວກັບການຖົກຖຽງເລື່ອງມາດຕະຖານຄຳໃນຊຸມປີ 1930. ການອ່ານປຶ້ມນີ້ຄຽງຄູ່ກັບນັກວິຈານທີ່ດີ ຄຸ້ມຄ່າກວ່າການອ່ານມັນສອງຄັ້ງ.$$)
  ))
  ),
  glossary_en = jsonb_build_array(
    jsonb_build_object('term', $$Salability$$, 'body', $$How easily a good can be sold on again — across space, across scales, and across time.$$),
    jsonb_build_object('term', $$Stock-to-flow ratio$$, 'body', $$Existing stock divided by annual new production. Higher means harder.$$),
    jsonb_build_object('term', $$Hard vs easy money$$, 'body', $$Hard money resists supply increases when demand rises; easy money does not.$$),
    jsonb_build_object('term', $$Time preference$$, 'body', $$How steeply a person discounts the future. Lower means more saving, longer horizons.$$),
    jsonb_build_object('term', $$Cantillon effect$$, 'body', $$Newly created money reaches some people before others, redistributing toward the early recipients.$$),
    jsonb_build_object('term', $$Malinvestment$$, 'body', $$Capital committed to projects that only appeared viable because credit was artificially cheap.$$),
    jsonb_build_object('term', $$Unforgeable costliness$$, 'body', $$Value that comes from being expensive to produce and impossible to fake cheaply.$$),
    jsonb_build_object('term', $$Difficulty adjustment$$, 'body', $$Bitcoin's automatic retuning of mining difficulty so that supply stays on schedule regardless of effort.$$)
  ),
  glossary_lo = jsonb_build_array(
    jsonb_build_object('term', $$ຄວາມສາມາດຂາຍຕໍ່ໄດ້ (Salability)$$, 'body', $$ຄວາມງ່າຍໃນການຂາຍສິນຄ້າໃດໜຶ່ງອອກຄືນ — ໃນທົ່ວພື້ນທີ່, ໃນທົ່ວຂະໜາດ ແລະ ໃນທົ່ວເວລາ.$$),
    jsonb_build_object('term', $$ອັດຕາສ່ວນ Stock-to-flow$$, 'body', $$ຄັງສະສົມທີ່ມີຢູ່ ຫານດ້ວຍການຜະລິດໃໝ່ຕໍ່ປີ. ຍິ່ງສູງ ຍິ່ງແຂງ.$$),
    jsonb_build_object('term', $$ເງິນແຂງ ທຽບກັບ ເງິນອ່ອນ$$, 'body', $$ເງິນແຂງຕ້ານທານການເພີ່ມປະລິມານເມື່ອຄວາມຕ້ອງການສູງຂຶ້ນ; ເງິນອ່ອນບໍ່ຕ້ານທານ.$$),
    jsonb_build_object('term', $$Time preference$$, 'body', $$ລະດັບທີ່ຄົນຫຼຸດຄ່າອະນາຄົດ. ຍິ່ງຕ່ຳ ຍິ່ງອອມຫຼາຍ ແລະ ວາງແຜນໄກຂຶ້ນ.$$),
    jsonb_build_object('term', $$ປະກົດການ Cantillon$$, 'body', $$ເງິນທີ່ຖືກສ້າງໃໝ່ ໄປເຖິງບາງຄົນກ່ອນຄົນອື່ນ ແລ້ວແຈກຢາຍຄວາມຮັ່ງມີຄືນໄປຫາຄົນທີ່ໄດ້ຮັບກ່ອນ.$$),
    jsonb_build_object('term', $$ການລົງທຶນຜິດພາດ (Malinvestment)$$, 'body', $$ທຶນທີ່ຖືກນຳໄປລົງໃນໂຄງການທີ່ເບິ່ງຄືວ່າຄຸ້ມຄ່າ ພຽງເພາະສິນເຊື່ອຖືກເຮັດໃຫ້ຖືກແບບປະດິດ.$$),
    jsonb_build_object('term', $$ຕົ້ນທຶນທີ່ປອມແປງບໍ່ໄດ້ (Unforgeable costliness)$$, 'body', $$ມູນຄ່າທີ່ມາຈາກການແພງໃນການຜະລິດ ແລະ ປອມແປງລາຄາຖືກບໍ່ໄດ້.$$),
    jsonb_build_object('term', $$ການປັບຄວາມຍາກ (Difficulty adjustment)$$, 'body', $$ການປັບຄວາມຍາກໃນການຂຸດ Bitcoin ໂດຍອັດຕະໂນມັດ ເພື່ອໃຫ້ປະລິມານອອກຕາມກຳນົດເວລາ ບໍ່ວ່າຄວາມພະຍາຍາມຈະຫຼາຍປານໃດ.$$)
  ),
  reflection_questions_en = array[$$If hardness is the property that matters most, why did societies repeatedly adopt easier money anyway — was it ignorance, or was something being traded off?$$, $$The book blames debasement for short-term thinking. What else changed over the same century that might explain the same pattern?$$, $$If falling prices raise the real burden of existing debts, how would a heavily indebted economy transition to a hard money without a wave of defaults?$$, $$Ammous says Bitcoin is for saving, not spending. Can something become money if almost nobody spends it?$$, $$Which of the book's specific predictions can you now check against what has happened since 2018 — and how do they score?$$],
  reflection_questions_lo = array[$$ຖ້າຄວາມແຂງແມ່ນຄຸນສົມບັດທີ່ສຳຄັນທີ່ສຸດ ເປັນຫຍັງສັງຄົມຈຶ່ງເລືອກໃຊ້ເງິນທີ່ອ່ອນກວ່າຊ້ຳແລ້ວຊ້ຳອີກ — ເປັນເພາະຄວາມບໍ່ຮູ້ ຫຼື ມີບາງຢ່າງທີ່ຖືກແລກປ່ຽນ?$$, $$ປຶ້ມນີ້ໂທດການເຮັດໃຫ້ເງິນອ່ອນຄ່າ ວ່າເປັນສາເຫດຂອງການຄິດໄລຍະສັ້ນ. ມີຫຍັງອີກທີ່ປ່ຽນແປງໃນສະຕະວັດດຽວກັນ ທີ່ອາດອະທິບາຍຮູບແບບດຽວກັນນີ້ໄດ້?$$, $$ຖ້າລາຄາທີ່ຫຼຸດລົງເພີ່ມພາລະໜີ້ສິນທີ່ແທ້ຈິງ ເສດຖະກິດທີ່ເປັນໜີ້ໜັກຈະປ່ຽນໄປສູ່ເງິນແຂງໄດ້ແນວໃດ ໂດຍບໍ່ເກີດຄື້ນຄົນຜິດນັດຊຳລະໜີ້?$$, $$Ammous ບອກວ່າ Bitcoin ມີໄວ້ອອມ ບໍ່ແມ່ນໃຊ້ຈ່າຍ. ບາງສິ່ງຈະກາຍເປັນເງິນໄດ້ບໍ ຖ້າເກືອບບໍ່ມີໃຜໃຊ້ຈ່າຍມັນ?$$, $$ຄຳທຳນາຍສະເພາະຂໍ້ໃດຂອງປຶ້ມ ທີ່ທ່ານສາມາດກວດສອບໄດ້ແລ້ວ ກັບສິ່ງທີ່ເກີດຂຶ້ນຕັ້ງແຕ່ປີ 2018 — ແລະ ມັນຖືກຫຼືຜິດ?$$],
  key_takeaways_en = array[$$Money is whatever is most salable, and salability across time is the test that decides which money survives.$$, $$Stock-to-flow measures hardness: anything easy to produce more of gets produced, and its savers get diluted.$$, $$Every historical money failed the same way — someone found a cheaper way to make it.$$, $$Gold's chemistry made it hard; its weight forced it into vaults, and vaults could be captured by states.$$, $$1914 broke convertibility and 1971 ended it; we live in the first era with no monetary anchor outside politics.$$, $$The money you save in shapes how far ahead it is worth planning — economically solid, culturally overreached.$$, $$New money enters at specific points, so it redistributes toward whoever receives it first.$$, $$The difficulty adjustment, not the 21-million cap, is the real innovation: effort no longer creates supply.$$, $$Ammous argues for savings and settlement, not payments, and rejects most of what surrounds Bitcoin.$$, $$Take the framework seriously; treat the historical and cultural verdicts as claims to test.$$],
  key_takeaways_lo = array[$$ເງິນຄືສິ່ງທີ່ຂາຍຕໍ່ໄດ້ງ່າຍທີ່ສຸດ ແລະ ຄວາມສາມາດຂາຍຕໍ່ໄດ້ຂ້າມເວລາ ຄືບົດທົດສອບທີ່ຕັດສິນວ່າເງິນໃດຢູ່ລອດ.$$, $$Stock-to-flow ວັດແທກຄວາມແຂງ: ສິ່ງໃດຜະລິດເພີ່ມງ່າຍ ຈະຖືກຜະລິດເພີ່ມ ແລະ ຄົນອອມໃນສິ່ງນັ້ນຈະຖືກເຈືອຈາງ.$$, $$ເງິນທຸກຊະນິດໃນປະຫວັດສາດລົ້ມເຫຼວແບບດຽວກັນ — ມີຄົນຊອກຫາວິທີຜະລິດມັນຖືກກວ່າ.$$, $$ເຄມີຂອງຄຳເຮັດໃຫ້ມັນແຂງ; ນ້ຳໜັກຂອງມັນບັງຄັບໃຫ້ຕ້ອງເກັບໃນຫ້ອງນິລະໄພ ແລະ ຫ້ອງນິລະໄພຖືກລັດຍຶດຄອງໄດ້.$$, $$ປີ 1914 ຕັດການແລກປ່ຽນເປັນຄຳ ແລະ ປີ 1971 ຈົບມັນ; ພວກເຮົາຢູ່ໃນຍຸກທຳອິດທີ່ບໍ່ມີຫຼັກຄ້ຳການເງິນນອກເໜືອການເມືອງ.$$, $$ເງິນທີ່ທ່ານອອມໄວ້ ກຳນົດວ່າຄວນວາງແຜນໄກປານໃດ — ໜັກແໜ້ນທາງເສດຖະສາດ ແຕ່ຂະຫຍາຍໄກເກີນໄປທາງວັດທະນະທຳ.$$, $$ເງິນໃໝ່ເຂົ້າສູ່ຈຸດສະເພາະກ່ອນ ດັ່ງນັ້ນມັນຈຶ່ງແຈກຢາຍຄວາມຮັ່ງມີຄືນ ໄປຫາໃຜກໍ່ຕາມທີ່ໄດ້ຮັບກ່ອນ.$$, $$ການປັບຄວາມຍາກ ບໍ່ແມ່ນເພດານ 21 ລ້ານ ຄືນະວັດຕະກຳທີ່ແທ້ຈິງ: ຄວາມພະຍາຍາມບໍ່ສ້າງປະລິມານເພີ່ມອີກຕໍ່ໄປ.$$, $$Ammous ສະໜັບສະໜູນມັນເພື່ອການອອມ ແລະ ການຊຳລະສະສາງ ບໍ່ແມ່ນການຈ່າຍເງິນ ແລະ ປະຕິເສດເກືອບທຸກຢ່າງທີ່ຫຸ້ມຮອບ Bitcoin.$$, $$ຖືກອບແນວຄິດຢ່າງຈິງຈັງ; ຖືຄຳຕັດສິນທາງປະຫວັດສາດ ແລະ ວັດທະນະທຳ ເປັນຄຳກ່າວອ້າງທີ່ຕ້ອງທົດສອບ.$$]
where book_id = '6a9b881f-0a1a-40a3-8e3f-ee1b18b6832e';
